import json
import os
import signal
import threading
import time

import zmq
from robot.errors import ExecutionFailed
from robot.running import EXECUTION_CONTEXTS
from robot.running import Keyword

from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.server_commands import TEST


class Heartbeat(threading.Thread):
    """Heart beat besed on python thread"""

    def __init__(self, context, host, port, heartbeat_message_log=False):
        """

        :param context:
        :param host:
        :param port:
        :param heartbeat_message_log:
        """
        super(Heartbeat, self).__init__()

        self.zmq_context = context
        self.poller = zmq.Poller()
        self.pusher = zmq.Poller()
        self.continue_running = True
        self.failed_occured = False
        self.heartbeat_message_log = heartbeat_message_log
        try:
            self.SOCKET_HEARTBEAT = self.zmq_context.socket(zmq.REQ)
            self.SOCKET_HEARTBEAT.setsockopt(zmq.LINGER, 0)
            self.SOCKET_HEARTBEAT.connect("tcp://%s:%s" % (host, port))
            self.poller.register(self.SOCKET_HEARTBEAT, zmq.POLLIN)
            self.pusher.register(self.SOCKET_HEARTBEAT, zmq.POLLOUT)
            if self.heartbeat_message_log:
                Keyword(name='Log', args=["[HEARTBEAT] connected to %s:%s" %
                                          (host, port)]).run(EXECUTION_CONTEXTS.current)
        except Exception:
            self.failed_occured = True
            self.continue_running = False
            os.kill(os.getpid(), signal.SIGUSR1)

        self.heartbeat_timer_start = 0
        self.heartbeat_timer_current = time.time()
        self.last_heartbeat_recieved = time.time()
        self.heartbeat_timer_difference = 0
        self.heartbeat_difference = 0

        self.HEARTBEAT_INTERVAL = 15
        self.HEARTBEAT_TIMER = 60

        self.retry_times_for_sending = 5
        self.retry_times_for_recieving = 5
        self.sending_timeout = 500
        self.recieving_timeout = 500

    def stop(self):
        """
        Stop heartbeat mechanism
        :return: True
        """
        if not self.failed_occured:
            self._send_heartbeat(test_running=False)
            self._recieve_heartbeat()
        self.continue_running = False
        if self.SOCKET_HEARTBEAT:
            self.SOCKET_HEARTBEAT.close()
            self.SOCKET_HEARTBEAT = None
        self.zmq_context = None
        return True

    def __del__(self):
        self.continue_running = False
        if self.SOCKET_HEARTBEAT:
            self.SOCKET_HEARTBEAT.close()
            self.SOCKET_HEARTBEAT = None
        if self.zmq_context:
            self.zmq_context = None

    def _send_heartbeat(self, test_running=True):
        """
        Method for sending heartbeat to PC Server with initial probe to see if message will reach the recepient

        :param message:             Message to send over socket
        :type message:              string

        :return:                    True if message send succeded, False if messaged send failed
        :rtype:                     bool
        """
        retried = 0
        while retried < self.retry_times_for_sending:
            try:
                socket = dict(self.pusher.poll(self.sending_timeout))
                if self.SOCKET_HEARTBEAT in socket:
                    self.SOCKET_HEARTBEAT.send_string(json.dumps({"command": TEST.HEARTBEAT.value,
                                                                  "test_running": test_running}))
                    if self.heartbeat_message_log:
                        Keyword(name='Log', args=["[HEARTBEAT] sent"]).run(EXECUTION_CONTEXTS.current)
                    return True
                else:
                    retried += 1
            except Exception:
                pass
        return False

    def _recieve_heartbeat(self):
        try:
            retried = 0
            while retried < self.retry_times_for_recieving:
                sockets = dict(self.poller.poll(self.recieving_timeout))
                if self._read_heartbeat_socket(sockets):
                    return True
                retried += 1
        except Exception:
            pass
        return False

    def _read_heartbeat_socket(self, sockets):
        if self.SOCKET_HEARTBEAT in sockets:
            message = None
            try:
                message = self.SOCKET_HEARTBEAT.recv_string()
                json_message = json.loads(message)
                return self._check_recv_heartbeat(json_message)
            except UnicodeDecodeError:
                pass
            except ValueError:
                if message and self.heartbeat_message_log:
                    Keyword(name='Log', args=["Received non-JSON message from [HEARTBEAT]: %s" %
                                              message]).run(EXECUTION_CONTEXTS.current)

    def _check_recv_heartbeat(self, json_message):
        command = json_message["command"]
        if command == TEST.HEARTBEAT.value:
            # Keyword(name='Log', args=["[HEARTBEAT] recieved",
            #                           "level=trace"]).run(EXECUTION_CONTEXTS.current)
            if self.heartbeat_message_log:
                Keyword(name='Log', args=["[HEARTBEAT] recieved"]).run(EXECUTION_CONTEXTS.current)
            self.last_heartbeat_recieved = time.time()
            return True

    def run(self):
        """
        Start heartbeat mechanism
        :return: True
        """
        try:
            while self.continue_running:
                self._perform_heartbeat()
                self._check_fail_condition()
                time.sleep(1)
            if self.failed_occured:
                os.kill(os.getpid(), signal.SIGUSR2)
        except ExecutionFailed:
            return
        except Exception:
            pass

    def _check_fail_condition(self):
        if self.heartbeat_difference >= self.HEARTBEAT_TIMER:
            self.failed_occured = True
            self.continue_running = False

    def _perform_heartbeat(self):
        self.heartbeat_timer_current = time.time()
        self.heartbeat_timer_difference = self.heartbeat_timer_current - self.heartbeat_timer_start
        if self.heartbeat_timer_difference >= self.HEARTBEAT_INTERVAL:
            self.heartbeat_timer_start = time.time()
            self._send_heartbeat()
            self._recieve_heartbeat()
        self.heartbeat_timer_current = time.time()
        self.heartbeat_difference = self.heartbeat_timer_current - self.last_heartbeat_recieved
